(function() {
  // Initialize drop area
  const dropArea = document.createElement('div');
  dropArea.className = 'imgur-drop-area';

  const iconElement = document.createElement('div');
  iconElement.className = 'imgur-drop-area-icon';
  dropArea.appendChild(iconElement);

  document.body.appendChild(dropArea);

  // Create notification element
  const notification = document.createElement('div');
  notification.className = 'upload-notification';
  document.body.appendChild(notification);

  // Imgur API client ID (you'll need to register your application)
  const IMGUR_CLIENT_ID = 'YOUR_CLIENT_ID'; // Replace with your actual client ID

  // Show drop area when dragging starts
  document.addEventListener('dragover', (e) => {
    e.preventDefault();
    if (isDraggingImage(e)) {
      dropArea.classList.add('active');
    }
  });

  // Hide drop area when dragging ends outside of it
  document.addEventListener('dragleave', (e) => {
    if (e.clientX <= 0 || e.clientY <= 0 || 
        e.clientX >= window.innerWidth || e.clientY >= window.innerHeight) {
      dropArea.classList.remove('active');
      dropArea.classList.remove('hover');
    }
  });

  // Handle drop area hover effect
  dropArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropArea.classList.add('hover');
  });

  dropArea.addEventListener('dragleave', (e) => {
    dropArea.classList.remove('hover');
  });

  // Handle drop
  dropArea.addEventListener('drop', async (e) => {
    e.preventDefault();

    dropArea.classList.remove('active');
    dropArea.classList.remove('hover');

    const files = e.dataTransfer.files;
    if (files.length > 0 && files[0].type.startsWith('image/')) {
      showNotification('Uploading image...');
      uploadToImgur(files[0]);
    }
  });

  // Hide drop area when drag ends
  document.addEventListener('dragend', () => {
    dropArea.classList.remove('active');
    dropArea.classList.remove('hover');
  });

  document.addEventListener('drop', (e) => {
    if (!dropArea.contains(e.target)) {
      e.preventDefault(); // Prevent default browser behavior
      dropArea.classList.remove('active');
      dropArea.classList.remove('hover');
    }
  });

  // Helper function to check if dragged item is an image
  function isDraggingImage(e) {
    if (e.dataTransfer && e.dataTransfer.types) {
      if (e.dataTransfer.types.indexOf('Files') >= 0) {
        return true;
      }
      if (e.dataTransfer.types.indexOf('text/uri-list') >= 0) {
        return true;
      }
    }
    return false;
  }

